#!/usr/bin/env bash
# Generated by OrchestKit Claude Plugin
# Created: 2026-08-22

# paired-probe.sh -- refuse a verdict that a probe did not earn.
#
# THE THREE GATES
#   1. DIFFERENTIAL  run the check where the fault IS and where it IS NOT.
#                    Identical output means the probe is blind. Not evidence.
#   2. NON-EMPTY     a probe that examined zero items is could-not-observe,
#                    never "clean". Zero and clean must not print the same.
#   3. EXIT-AWARE    a non-zero exit from the probe itself is a third outcome,
#                    distinct from both verdicts. Never swallowed.
#
# USAGE
#   paired-probe.sh --name "<what is being tested>" \
#                   --present "<command where the fault EXISTS>" \
#                   --absent  "<command where the fault DOES NOT exist>"
#
#   paired-probe.sh --name "..." --measure "<command>" --min-count N
#       Single-shot form when the fault cannot be staged (a live sweep):
#       asserts the probe actually examined at least N items.
#
# EXIT CODES
#   0 discriminates (or met its minimum count) · 1 BLIND · 2 usage · 3 could-not-observe
#
# strict-mode: opt-out this tool's entire purpose is to RUN commands that fail
# and compare their exit codes; `set -e` would abort on the first failing arm,
# which is the expected case, not an error. -u and pipefail are kept.
set -uo pipefail

# WHY THIS EXISTS. A check that prints the same thing whether or not the fault
# is present has measured nothing, yet still returns an answer that gets acted
# on. Four real instances, one session, 2026-08-21:
#   asked the local ref cache "is this branch pushed?"  -> "no" for pushed branches
#   asked "is the branch on origin?" after a squash     -> "no" for merged work
#   diffed a stale worktree against main                -> flagged main vs itself
#   wrote to a blocked path, swallowed the error        -> printed "safe to prune"
#                                                          having measured ZERO items
# All four were confidently wrong, none failed loudly, three were caught by peers.

NAME=""; PRESENT=""; ABSENT=""; MEASURE=""; MIN_COUNT=""
while [ $# -gt 0 ]; do
  case "$1" in
    --name)      NAME="${2:-}"; shift 2 ;;
    --present)   PRESENT="${2:-}"; shift 2 ;;
    --absent)    ABSENT="${2:-}"; shift 2 ;;
    --measure)   MEASURE="${2:-}"; shift 2 ;;
    --min-count) MIN_COUNT="${2:-}"; shift 2 ;;
    -h|--help)   sed -n '2,24p' "$0"; exit 0 ;;
    *) printf 'paired-probe: unknown argument: %s\n' "$1" >&2; exit 2 ;;
  esac
done

[ -n "$NAME" ] || { echo "paired-probe: --name is required" >&2; exit 2; }

RED=$'\033[0;31m'; GRN=$'\033[0;32m'; OFF=$'\033[0m'

run() {  # $1 = command; echoes "<rc>\x1f<output>"
  local out rc
  out=$(eval "$1" 2>&1); rc=$?
  printf '%s\037%s' "$rc" "$out"
}

# ---------------------------------------------------------------- single-shot
if [ -n "$MEASURE" ]; then
  [ -n "$MIN_COUNT" ] || { echo "paired-probe: --measure requires --min-count" >&2; exit 2; }
  res=$(run "$MEASURE"); rc="${res%%$'\037'*}"; out="${res#*$'\037'}"
  if [ "$rc" -ne 0 ]; then
    printf '%sCOULD-NOT-OBSERVE%s  %s\n' "$RED" "$OFF" "$NAME"
    printf '  the probe itself exited %s. That is not a clean result.\n' "$rc"
    printf '  %s\n' "$(printf '%s' "$out" | head -3)"
    exit 3
  fi
  n=$(printf '%s' "$out" | awk 'NF{c++} END{print c+0}')
  if [ "$n" -lt "$MIN_COUNT" ]; then
    printf '%sBLIND%s  %s\n' "$RED" "$OFF" "$NAME"
    printf '  examined %s item(s), expected at least %s.\n' "$n" "$MIN_COUNT"
    printf '  A sweep that measured nothing must not report "clean".\n'
    exit 1
  fi
  printf '%sMEASURED%s  %s  (%s items)\n' "$GRN" "$OFF" "$NAME" "$n"
  exit 0
fi

# ---------------------------------------------------------------- differential
if [ -z "$PRESENT" ] || [ -z "$ABSENT" ]; then
  echo "paired-probe: need --present and --absent (or --measure with --min-count)" >&2
  exit 2
fi

p=$(run "$PRESENT"); prc="${p%%$'\037'*}"; pout="${p#*$'\037'}"
a=$(run "$ABSENT");  arc="${a%%$'\037'*}"; aout="${a#*$'\037'}"

if [ "$prc" -gt 125 ] || [ "$arc" -gt 125 ]; then
  printf '%sCOULD-NOT-OBSERVE%s  %s\n' "$RED" "$OFF" "$NAME"
  printf '  an arm died (present rc=%s, absent rc=%s). Fix the probe before judging.\n' "$prc" "$arc"
  exit 3
fi

if [ "$pout" = "$aout" ] && [ "$prc" = "$arc" ]; then
  printf '%sBLIND%s  %s\n' "$RED" "$OFF" "$NAME"
  printf '  both arms printed the same thing (rc=%s), so the probe cannot see the fault.\n' "$prc"
  printf '  output was: %s\n' "$(printf '%s' "$pout" | head -1)"
  printf '  Do NOT report a verdict from this check. Change what it asks.\n'
  exit 1
fi

printf '%sDISCRIMINATES%s  %s\n' "$GRN" "$OFF" "$NAME"
printf '  fault present -> rc=%s  %s\n' "$prc" "$(printf '%s' "$pout" | head -1)"
printf '  fault absent  -> rc=%s  %s\n' "$arc" "$(printf '%s' "$aout" | head -1)"
exit 0
